insert into blogs(id, user_id, sport_code, title, content, image_urls, related_type, related_id, related_title, related_cover_url, related_price, liked, status, created_at) values
(1, 1, 'badminton', '羽毛球：新手第一套装备怎么选', '从价格、容错和使用频率出发选择，不必一步到顶。优点是容易上手，缺点是高强度对抗上限有限。', '/api/files/81/download', 'EQUIPMENT', 1, '轻羽 5U 新手羽毛球拍', '/api/files/56/download', 89.00, 29, 1, date_sub(now(), interval 3 hour)),
(2, 2, 'badminton', '羽毛球：下班后一小时场馆体验', '交通和可预约时段比装修更重要。这个选择离地铁近、价格友好，但晚高峰会比较拥挤。', '/api/files/82/download', 'VENUE_PRODUCT', 2, '羽毛球 晚间黄金单场 1 小时', '/api/files/31/download', 58.00, 46, 1, date_sub(now(), interval 6 hour)),
(3, 3, 'badminton', '羽毛球：进阶训练装备实测', '连续训练后更关注支撑和稳定。它的实战反馈直接，但对动作基础和体能有一定要求。', '/api/files/83/download', 'EQUIPMENT', 2, '疾风缓震羽毛球鞋', '/api/files/57/download', 329.00, 63, 1, date_sub(now(), interval 9 hour)),
